CREATE TABLE IF NOT EXISTS rl."bs_gs_visitas" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "id" double precision,
  "codigo" extensions.citext,
  "fecha" timestamp,
  "empresa" extensions.citext,
  "fundo" extensions.citext,
  "sede" extensions.citext,
  "visitante" extensions.citext,
  "acompanantes" extensions.citext,
  "personas_presentes" double precision,
  "respuestas" extensions.citext,
  "puntaje" double precision,
  "items_ok" double precision,
  "items_obs" double precision,
  "items_na" double precision,
  "hallazgos" extensions.citext,
  "compromisos" extensions.citext,
  "responsable_compromiso" extensions.citext,
  "fecha_compromiso" timestamp,
  "estado" extensions.citext,
  "fecha_cierre" timestamp,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_gs_visitas_ux_bs_gs_visitas_fila" ON rl."bs_gs_visitas" ("fila");
CREATE TABLE IF NOT EXISTS rl."bs_gs_visitas__carga" (
