  "items_na" double precision,
  "hallazgos" extensions.citext,
  "compromisos" extensions.citext,
  "responsable_compromiso" extensions.citext,
  "fecha_compromiso" timestamp,
  "estado" extensions.citext,
  "fecha_cierre" timestamp,
  "created_by" extensions.citext,
